2.query:
timeseries {
  all = sum(o11yag.tasks),
  err = sum(o11yag.tasks, filter: {outcome == "error"})
}
| fieldsAdd error_rate = arraySum(err) * 100.0 / arraySum(all)
| fields error_rate

6.query:
timeseries t = sum(o11yag.tasks), by: {intent}
| fieldsAdd tickets = arraySum(t)
| fields intent, tickets

7.query:
timeseries {
  avg_calls = avg(o11yag.task.llm_calls),
  p90_calls = percentile(o11yag.task.llm_calls, 90, rollup: avg)
}, by: {intent}

8.query:
timeseries {
  avg_ms = avg(o11yag.task.latency),
  p95_ms = percentile(o11yag.task.latency, 95, rollup: avg)
}, by: {intent}

12.query:
timeseries {
  top_score = avg(o11yag.retrieval.top_score),
  hits = avg(o11yag.retrieval.hits)
}, by: {collection}
